<?php get_header();the_post();$minutes=max(1,ceil(str_word_count(wp_strip_all_tags(get_the_content()))/220));$fallback=bajwa_blog_image_name(get_the_ID());$small=file_exists(BAJWA_PREMIUM_DIR.'assets/images/'.$fallback.'-600.jpg')?'-600':'-960';$image=get_theme_file_uri('assets/images/'.$fallback.$small.'.jpg');?>
<main id="main"><header class="page-hero page-hero--image article-image-hero"><div class="page-hero__media"><?php if(has_post_thumbnail()):the_post_thumbnail('full',array('class'=>'page-hero__image','fetchpriority'=>'high','decoding'=>'async'));else:?><img class="page-hero__image" src="<?php echo esc_url($image);?>" width="<?php echo '-600'===$small?'600':'960';?>" height="<?php echo '-600'===$small?'450':'540';?>" alt="Illustration for <?php echo esc_attr(get_the_title());?>" fetchpriority="high" decoding="async"><?php endif;?><span class="page-hero__overlay"></span></div><div class="container page-hero__content"><p class="eyebrow">Bajwa CPA insights</p><h1><?php the_title();?></h1><div class="article-meta"><span><?php echo esc_html(get_the_date('F j, Y'));?></span><span><?php echo esc_html($minutes);?> min read</span></div></div></header>
<article class="section article-section"><div class="container article-layout"><div class="article-prose"><div class="article-share"><span>Article</span><span></span></div><?php the_content();?><div class="article-end"><strong>Need advice for your situation?</strong><p>General information is a starting point. Speak with our team for professional guidance shaped around your circumstances.</p><a class="button button--navy" href="<?php echo esc_url(home_url('/contact/'));?>">Talk with Bajwa CPA</a></div></div><aside class="article-aside"><p class="eyebrow">Professional guidance</p><h2>Make the next decision with clarity.</h2><p>Tax rules and deadlines change. We help you understand what applies to you.</p><a class="text-link" href="<?php echo esc_url(home_url('/contact/'));?>">Contact our team <?php echo bajwa_icon('arrow');?></a></aside></div></article><section class="section section--mist related-posts"><div class="container"><p class="eyebrow">Continue reading</p><h2>More insights from Bajwa CPA</h2><div class="card-grid"><?php $related=new WP_Query(array('post_type'=>'post','posts_per_page'=>3,'post__not_in'=>array(get_the_ID()),'no_found_rows'=>true,'ignore_sticky_posts'=>true));while($related->have_posts()):$related->the_post();?><article class="post-card"><p class="eyebrow"><?php echo esc_html(get_the_date());?></p><h3><a href="<?php the_permalink();?>"><?php the_title();?></a></h3><p><?php echo esc_html(wp_trim_words(get_the_excerpt(),18));?></p><a class="text-link" href="<?php the_permalink();?>">Read article <?php echo bajwa_icon('arrow');?></a></article><?php endwhile;wp_reset_postdata();?></div></div></section></main><?php get_footer();?>
